void main() {
  vec2 lot = floor(uv * 32.0);
  vec2 shuffle = seed * vec2(7.13, 3.71);
  vec2 block = floor(lot / 4.0) + 3.0 + shuffle;
  float park = step(1.0 - parks, ghee_hash(block));
  float water = step(1.0 - ponds, ghee_hash(block + 19.0));
  gl_FragColor = vec4(park * mix(0.75, 1.0, water), ghee_hash(lot + shuffle), ghee_hash(lot + 7.0 + shuffle), 1.0);
}

void main() {
  vec2 p = uv * 4.0 + vec2(iTime * wind, iTime * wind * 0.4);
  float n = ghee_noise(p) * 0.65 + ghee_noise(p * 2.3 + 5.0) * 0.35;
  gl_FragColor = vec4(vec3(smoothstep(0.6, 0.68, n)), 1.0);
}

void main() {
  float t = radians(tilt);
  float a = radians(yaw);
  vec3 forward = vec3(sin(a) * cos(t), cos(a) * cos(t), -sin(t));
  vec3 right = vec3(cos(a), -sin(a), 0.0);
  vec3 up = vec3(sin(a) * sin(t), cos(a) * sin(t), cos(t));
  vec2 q = (uv - 0.5) * vec2(2.0 * iResolution.x / iResolution.y, -2.0) * tan(radians(fov) * 0.5);
  vec3 ray = forward + q.x * right + q.y * up;
  vec3 eye = vec3(0.5 + pan_x * right.xy + pan_y * vec2(sin(a), cos(a)), 0.0) - forward / zoom;
  float far = 8.0;
  if (ray.z < 0.0) far = min(far, -eye.z / ray.z * zoom);
  vec2 board = eye.xy + ray.xy * far / zoom;
  vec3 col = texture2D(iChannel0, 1.0 - abs(1.0 - mod(board, 2.0))).rgb;
  gl_FragColor = vec4(mix(col, haze, clamp(0.3 * (far - 1.2), 0.0, 1.0)), clamp(1.5 - 1.0 / far, 0.0, 1.0));
}

void main() {
  vec2 px = spread / iChannelResolution[0].xy;
  vec3 sum = vec3(0.0);
  float total = 0.0;
  for (int x = -2; x <= 2; x++) {
    for (int y = -2; y <= 2; y++) {
      float w = exp(-float(x * x + y * y) / 5.0);
      sum += w * texture2D(iChannel0, uv + vec2(float(x), float(y)) * px).rgb;
      total += w;
    }
  }
  gl_FragColor = vec4(sum / total, 1.0);
}

void main() {
  vec3 col = vec3(0.0);
  if (gl_FragCoord.x >= 0.0) col = texture2D(iChannel0, uv).rgb;
  vec2 q = (uv - 0.5) * vec2(iResolution.x / iResolution.y, 1.0);
  col *= 1.0 - vignette * dot(q, q);
  col += (ghee_hash(floor(uv * iResolution.xy) + fract(iTime) * 97.0) - 0.5) * grain;
  gl_FragColor = vec4(col, 1.0);
}
